import json

deployed = {
    "mfa-home":    {"stable": "/home/v7.js"},
    "mfa-trading": {"stable": "/trading/v1.js", "canary": "/trading/v2.js", "percent": 10},
}

def import_map(cohort):  # cohort: 사용자 쿠키에 든 1~100
    imports = {}
    for name, d in deployed.items():
        use_canary = "canary" in d and cohort <= d["percent"]
        imports[name] = d["canary"] if use_canary else d["stable"]
    return {"imports": imports}

for c in (3, 10, 11, 87):
    print(c, json.dumps(import_map(c)["imports"]))
n = sum(import_map(c)["imports"]["mfa-trading"].endswith("v2.js") for c in range(1, 101))
print("v2 를 받는 사람:", n, "/ 100")

# 3 {"mfa-home": "/home/v7.js", "mfa-trading": "/trading/v2.js"}
# 10 {"mfa-home": "/home/v7.js", "mfa-trading": "/trading/v2.js"}
# 11 {"mfa-home": "/home/v7.js", "mfa-trading": "/trading/v1.js"}
# 87 {"mfa-home": "/home/v7.js", "mfa-trading": "/trading/v1.js"}
# v2 를 받는 사람: 10 / 100
